sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    //ユーザー検索欄が変わる時に、フラグは「true」に変換する
    api.setState("flag", "true");
    //ユーザー検索欄の入力値を取得
    var user_name = api.state.user_name;
    //ログインユーザー情報を取得
    var phn_user = api.data.look_up_multiple_records_4.results;
    //予定情報を取得
    var phn_location = api.data.look_up_multiple_records_1.results;
    //ログインユーザー名を取得
    var user_login_name = api.context.session.user.userName;
    var str = "[";
    //予定情報を繰り返し
    var phn_group = api.data.look_up_multiple_records_5.results;
    //組織予定用JSON
    if (user_name != "") {
        for (var g = 0; g < phn_group.length; g++) {
            if (phn_group[g].u_yotei_shubetsu.value == 1) {
                str += '{' + '"id":' + '"' + "group" + phn_group[g].u_gurupu.displayValue + '",' +
                    '"title":' + '"' + "組織予定" + '",' +
                    '"isCollapsed":' + false + ',' +
                    '"showHeader":' + true + ',' +
                    '"textColor":' + '"",' +
                    '"children":[';
                str +=
                    '{' + '"id":' + '"' + "group" + phn_group[g].u_gurupu.displayValue + '",' +
                    '"title":' + '"' + phn_group[g].u_gurupu.displayValue + '"}';
                str += "]},";

            }
        }
    }
    for (var i = 0; i < phn_location.length; i++) {
        console.log("usertest timeline vertical2:" + phn_location[i].u_kanren_shien_taishosha.displayValue);
        //予定情報の参加者とユーザー検索欄の入力値が一致場合
        if (phn_location[i].u_kanren_shien_taishosha.displayValue == user_name) {
            str += '{' + '"id":' + '"' + phn_location[i].u_gurupu.displayValue + '",' +
                '"title":' + '"' + phn_location[i].u_gurupu.displayValue + '",' +
                '"isCollapsed":' + false + ',' +
                '"showHeader":' + true + ',' +
                '"textColor":' + '"",' +
                '"children":[';
            for (var j = 0; j < phn_user.length; j++) {
                if ((phn_user[j].department.displayValue == phn_location[i].u_gurupu.displayValue)) {
                    //ログインしているユーザー予定情報
                    str +=
                        '{' + '"id":' + '"' + "login_in" + '",' +
                        '"title":' + '"' + phn_user[0].user_name.displayValue + '"},';
                    //ユーザー検索欄の入力値の予定情報
                    str +=
                        '{' + '"id":' + '"' + phn_location[i].u_gurupu.displayValue + '",' +
                        '"title":' + '"' + phn_location[i].u_kanren_shien_taishosha.displayValue + '"},';
                } else {
                    //情報を取得できない場合
                    str +=
                        '{' + '"id":' + '"' + "" + '",' +
                        '"title":' + '"' + "" + '"},';
                }

                if (j == phn_user.length - 1) {
                    if (str.endsWith(",")) {
                        str = str.slice(0, -1);
                    }
                    str += "]}";
                }

            }
            if (i == phn_location.length - 1) {
                str += "]";
            } else {
                str += ",";
            }
            break;
        }
    }
    if (str !== "[") {
        //JSON 文字列の最後がカンマで終わっている場合は修正
        if (str.trim().endsWith(',')) {
            str = str.trim().slice(0, -1);
            str += "]";
        }
        api.setState("timeline_sections", str);
        //検索欄が空で、組織情報・ログイン中ユーザーの予定だけ表示
    } else {
        var phn_user = api.data.look_up_multiple_records_4.results;
        var phn_location = api.data.look_up_multiple_records_1.results;
        var str = "[";
        //組織予定用JSON
        for (var g = 0; g < phn_group.length; g++) {
            if (phn_group[g].u_yotei_shubetsu.value == 1) {
                str += '{' + '"id":' + '"' + "group" + phn_group[g].u_gurupu.displayValue + '",' +
                    '"title":' + '"' + "組織予定" + '",' +
                    '"isCollapsed":' + false + ',' +
                    '"showHeader":' + true + ',' +
                    '"textColor":' + '"",' +
                    '"children":[';
                str +=
                    '{' + '"id":' + '"' + "group" + phn_group[g].u_gurupu.displayValue + '",' +
                    '"title":' + '"' + phn_group[g].u_gurupu.displayValue + '"}';
                str += "]},";

            }
        }
        for (var i = 0; i < phn_location.length; i++) {
            console.log("usertest:" + phn_location[i].u_kanren_shien_taishosha.displayValue);
            if (phn_location[i].u_kanren_shien_taishosha.displayValue == user_login_name) {
                str += '{' + '"id":' + '"' + phn_location[i].u_gurupu.displayValue + '",' +
                    '"title":' + '"' + phn_location[i].u_gurupu.displayValue + '",' +
                    '"isCollapsed":' + false + ',' +
                    '"showHeader":' + true + ',' +
                    '"textColor":' + '"",' +
                    '"children":[';

                for (var j = 0; j < phn_user.length; j++) {
                    if (phn_user[j].department.displayValue == phn_location[i].u_gurupu.displayValue) {
                        str +=
                            '{' + '"id":' + '"' + "login_in" + '",' +
                            '"title":' + '"' + phn_location[i].u_kanren_shien_taishosha.displayValue + '"},';
                    }
                    if (j == phn_user.length - 1) {
                        if (str.endsWith(",")) {
                            str = str.slice(0, -1);
                        }
                        str += "]}";
                    }

                }
                if (i == phn_location.length - 1) {
                    str += "]";
                } else {
                    str += ",";
                }
            }
        }
        if (str !== "[") {
            if (str.trim().endsWith(',')) {
                str = str.trim().slice(0, -1);
                str += "]";
            }
            api.setState("timeline_sections", str);
        }
    }
}
